<?php
$ceoRelContext=$ceoSectionPdo?\App\Services\AiCostForecastV2Service::latestContext($ceoSectionPdo,$ceoTargetYm):array('available'=>false);
$ceoRelCategories=!empty($ceoRelContext['available'])?\App\Services\AiCostForecastV2Service::categoryRows($ceoSectionPdo,$ceoRelContext['analysis_date'],$ceoRelContext['target_ym'],0,$ceoRelContext['run_id']):array();
$ceoCategoryLabels=\App\Services\AiCostForecastV2Service::categoryLabels();$ceoRelIds=array();foreach($ceoRelCategories as $row)$ceoRelIds[]=(int)$row['project_id'];$ceoRelProjectMap=cpms_ai_project_name_map($ceoSectionPdo,$ceoRelIds);
